    }
};

/**
 * @method
 * @name dts_ACODE_OnLoadCompleted
 * @description dts_ACODE 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ACODE_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.panelMsg(panel_msg, "총 : " + $c.stf.FormatNumberEx(rowcount) + " 건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF80000.dts_ACODE_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_ACODE_OnLoadError
 * @description dts_ACODE 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ACODE_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_ACODE);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF80000.dts_ACODE_OnLoadError" });
    }
};

/**
 * @method
 * @name txb_FORM_CD_onkeypress
 * @description txb_FORM_CD onkeypress 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_FORM_CD_onkeypress = async function() {
    try {
        if (event.keyCode === 13) {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF80000.txb_FORM_CD_onkeypress" });
    }
};

