/**
 * @method
 * @name grd_ACPT_OnDblClick
 * @description grd_ACPT 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_ACPT_OnDblClick = async function(row, colid) {
    try {
        const AcptNo = dts_ACPT.getCellData(row, "ACPT_NO");
        // alert(AcptNo);
        await $c.stf.openDisclViewer(AcptNo, "R");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF80000.grd_ACPT_OnDblClick" });
    }
};

