    try {
        scwin.setOrder(row, colid);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF80000.grd_ACODE_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_RemoveOrder_onclick
 * @description 「순서제거」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_RemoveOrder_onclick = function() {
    try {
        dts_ACODE.setBroadcast(false);
        for (let i = 1; i <= dts_ACODE.getRowCount(); i++) {
            dts_ACODE.setCellData(i, "SORT_ORD", "");
        }
        dts_ACODE.setBroadcast(true, true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF80000.btn_RemoveOrder_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const vFORM_CD = txb_FORM_CD.getValue();
    const vFILTER = txb_FILTER.getValue();
    if (vFORM_CD === "") {
        await $c.win.alert("서식코드를 입력하세요.");
        txb_FORM_CD.focus();
        return;
    }
    url += "&FORM_CD=" + vFORM_CD;
    url += "&FILTER=" + vFILTER;
    url += "&SCREN_ID=" + 'ULDSTF80000.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    $c.stf.panelMsg(panel_msg, "로딩중...기다려주세요.");
    $c.stf.panelMsg(panel_msg2, "로딩중...기다려주세요.");
    const sbmOptions = {
        id : "sbm_dts_ACODE",
        action : "/DisclosureStatistics.do",
        ref : "",
        target : "dts_ACODE=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    url += "&FORM_CD=" + vFORM_CD;
    const sbmOptions2 = {
        id : "sbm_dts_ACPT",
        action : "/DisclosureStatistics.do",
        ref : "",
        target : "dts_ACPT=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name save
 * @description save 처리
 * @returns {void}
 * @hidden N
 */
scwin.save = function() {
    const res = window.confirm("저장?");
    if (res) {
        let url = "/DisclosureStatistics.do?method=saveOldDsclItems";
        url += "&SCREN_ID=" + 'ULDSTF80000.xml';
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_ACODE)";
        trs_Save.Post();
    }
};

/**
 * @method
 * @name filter
 * @description filter 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.filter = async function() {
    await scwin.search();
};

/**
 * @method
 * @name syncAcode
 * @description sync Acode 처리
 * @returns {void}
 * @hidden N
 */
scwin.syncAcode = function() {
    dts_ACODE.setBroadcast(false);
    for (let i = 1; i <= dts_ACODE.getRowCount(); i++) {
        const vSORT_ORD = dts_ACODE.getCellData(i, "SORT_ORD");
        if (dts_ACODE.getCellData(i, "SORT_ORD") !== "") {
            const vACODE = dts_ACODE.getCellData(i, "ACODE");
            const vELMT_KOR_NM = dts_ACODE.getCellData(i, "ELMT_KOR_NM");
            for (let j = 0; j <= dts_ACODE.getRowCount(); j++) {
                const vSORT_ORD2 = dts_ACODE.getCellData(j, "SORT_ORD");
                const vACODE2 = dts_ACODE.getCellData(j, "ACODE");
                if (vSORT_ORD2 === "") {
                    if (vACODE === vACODE2) {
                        dts_ACODE.setCellData(j, "SORT_ORD", vSORT_ORD);
                        dts_ACODE.setCellData(j, "ELMT_KOR_NM", vELMT_KOR_NM);
                    }
                    // continue;

                }
            }
        }
    }
    dts_ACODE.setBroadcast(true, true);
};

/**
 * @method
 * @name setOrder
 * @description grd_ACODE
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.setOrder = function(row, colid) {
    // grd_ACODE
    let sMax = 1;
    if (colid === "NEXT") {
        for (let i = 1; i <= dts_ACODE.getRowCount(); i++) {
            const sOrder = dts_ACODE.getCellData(i, "SORT_ORD");
            if (sOrder !== "") {
                if (sMax > parseInt(sOrder, 10)) {
                    txb_MAX.setValue(sMax + 1);
                } else {
                    sMax = parseInt(sOrder, 10);
                }
            }
        }
        dts_ACODE.setCellData(row, "SORT_ORD", txb_MAX.getValue());
    }
};

/**
 * @method
 * @name grd_ACODE_CanColumnPosChange
 * @description grd ACODE Can Column Pos Change 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_ACODE_CanColumnPosChange = function(row, colid) {
    return true;
};
